    C c;
    constructor(C _c) { c = _c; }
    function run(address caddress, address[] memory _tos, uint v) public payable {
        require(caddress.code.length == 0);
        require(_tos.length > 0);
        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;
        bool reverted;
        bool ok;
        try c.transfer(address(this), caddress, _tos, v) returns (bool r) {
            reverted = false;
            ok = r;
